export const ACADEMY_CONTENT = Object.freeze({"locale":"ar","lessons":[{"ep":1,"title":"بيتكوين واحد يكلف كل هذا. هل لا يزال بإمكاني شراء جزء منه؟","goal":"التمييز بين عدد العملات والمبلغ المنفق، ومعرفة أنه يمكن شراء البيتكوين في أجزاء عشرية.","task":"في لوحة التدريب، حوّل مبلغ إنفاق قدره 100 إلى كمية عملات. لا يتم إنشاء أي أمر حقيقي.","answer":"0.002 BTC (دون خصم الرسوم).","takeaways":["سعر بيتكوين واحد ليس هو سعر البداية.","البيتكوين ينقسم إلى أجزاء عشرية: إذا أنفقت 100 عند سعر 50,000 فستملك 0.002 BTC.","كل منصة تحدد حدها الأدنى للطلب ورسومها الخاصة، فتحقق من الأمرين أولاً."],"quiz":{"q":"سعر البيتكوين الواحد 50,000 USDT. أنفقت 100 USDT مع تجاهل الرسوم. ماذا تحصل؟","options":["لا شيء، تحتاج إلى عملة كاملة","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002. يمكنك امتلاك جزء من بيتكوين واحد."},"transcript":[{"t":0.25,"who":"sam","text":"عملة واحدة تكلف كل هذا؟ أموالي لا تكفي حتى لتذكرة الدخول."},{"t":9.25,"who":"nexubo","text":"هذا سعر عملة كاملة، وليس ما يجب عليك دفعه في كل مرة. البيتكوين أصل رقمي ويمكنك امتلاكه بأجزاء عشرية. عادة لا تشتري عملة كاملة."},{"t":25.25,"who":"narrator","text":"مسألة تدريبية افتراضية: لنفترض أن البيتكوين يساوي 50,000 USDT وأنفقت 100. بتجاهل الرسوم، يعادل ذلك 0.002 بيتكوين. هذا ليس سعر السوق اليوم."},{"t":45.25,"who":"sam","text":"وماذا يحدث عندما يتحرك السعر؟"},{"t":47,"who":"nexubo","text":"قد يبقى عدد العملات ثابتاً، لكن قيمتها ترتفع وتنخفض. الشراء بمبلغ قليل يقلل المخاطرة، لكنه لا يعني انعدام المخاطر."},{"t":62.25,"who":"nexubo","text":"يمكن تجزئتها، لكن ليست كل منصة تقبل أوامر متناهية الصغر. تحقق من الحد الأدنى والرسوم. أثناء التعلم، استخدم أموالاً تجريبية دون الحاجة للإيداع."},{"t":75.25,"who":"narrator","text":"هل يجب أن تشتري عملة بيتكوين كاملة؟ لا. تذكر: سعر العملة الواحدة ليس تكلفة البداية."},{"t":86.25,"who":"narrator","text":"معظم الصفقات تُسعّر بعملة USDT. ولكن هل USDT دولار حقيقي؟ نكتشف ذلك في الحلقة القادمة."},{"t":92.55,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":2,"title":"هل USDT دولار؟ ولماذا نراه في كل مكان عند شراء الكريبتو؟","goal":"فهم الغرض من العملات المستقرة وآلية ربطها ومخاطرها، ومعرفة أنك لا تحتاج دائماً لشراء USDT أولاً.","task":"صنّف 'الوديعة البنكية بالدولار' و'USDT' و'BTC' في الفئات الصحيحة.","answer":"عملة USDT هي عملة مستقرة، وهي نوع من الأصول المشفرة وليست وديعة بنكية بالدولار.","takeaways":["USDT عملة مستقرة مصممة لتبقى قريبة من دولار واحد، وليست وديعة مصرفية.","تستخدمها المنصات لتسعير الأصول ومبادلتها، لذلك ينتهي البيع غالباً برصيد USDT.","\"المستقرة\" هدف في التصميم: قد ينحرف السعر، وللاسترداد شروط."],"quiz":{"q":"أي عبارة عن USDT صحيحة؟","options":["إنها الدولارات الموجودة في حسابك المصرفي","إنها عملة مستقرة، وهي نوع من الأصول المشفرة","لا يمكن أن تبتعد أبداً عن دولار واحد"],"answer":1,"why":"تسعى USDT إلى تتبّع الدولار، لكنها أصل مشفر له مخاطر خاصة بالجهة المُصدرة والمنصة."},"transcript":[{"t":0.25,"who":"sam","text":"يُطلق عليه اسم تيثر، إذن هو في الأساس دولارات في البنك، أليس كذلك؟"},{"t":9.25,"who":"nexubo","text":"لا. عملة USDT، أو تيثر، هي عملة مستقرة صُممت لتبقى قريبة من دولار واحد. لكنها ليست دولارات في حسابك البنكي وليست نقوداً خالية من المخاطر."},{"t":25.25,"who":"narrator","text":"غالباً ما تستخدمها المنصات لتسعير الأصول وتداولها. يمكنك شراء البيتكوين بعملة USDT، وعند البيع قد تسترد USDT بدلاً من تحويل بنكي."},{"t":45.25,"who":"nexubo","text":"كلمة 'مستقرة' هي هدف تصميمي وليست ضماناً. قد ينحرف السعر، ولإصدارها واستردادها شروط. إذا كنت تحتفظ بها، فافهم مخاطر المصدر والمنصة."},{"t":62.25,"who":"sam","text":"هل يعني هذا أنني مجبر على شراء USDT قبل البيتكوين؟"},{"t":65.23,"who":"nexubo","text":"ليس دائماً. يعتمد توفر العملات وأزواج التداول على منطقتك والمنصة التي تستخدمها."},{"t":75.25,"who":"narrator","text":"ما الخطأ في هذه العبارة؟ العملة المستقرة ليست وعداً بحفظ رأس المال. افهم غرضها واعلم أنها قد تصبح غير مستقرة."},{"t":86.25,"who":"narrator","text":"إذا تعطل هاتفك الليلة، فهل تضيع عملاتك أيضاً؟ في الحلقة القادمة: أين توجد عملاتك في الواقع."},{"t":92.15,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":3,"title":"أين عملاتي؟ الفرق بين المنصة والمحفظة","goal":"التمييز بين حساب المنصة الاحتجازي ومحفظة الحفظ الذاتي، وفهم من يتحكم في الوصول ومن يتولى الاسترداد.","task":"طابق بين سيناريوهين: حساب تسجيل دخول على منصة تداول، ومحفظة حفظ ذاتي قياسية بعبارة استرداد.","answer":"يختلفان فيمن يملك السيطرة وكيفية الاسترداد. الحفظ الذاتي لا يعني الأمان التلقائي.","takeaways":["في حساب المنصة، تتولى المنصة بشكل أساسي إدارة الأصول والمفاتيح.","في المحفظة ذاتية الحفظ أنت من يتحكم في بيانات الدخول، ومسؤولية الاسترداد عليك.","قبل أن تختار، اسأل: من يملك صلاحية نقل الأصول؟"],"quiz":{"q":"فقدت عبارة الاسترداد لمحفظة ذاتية الحفظ عادية، ولا توجد لديك وسيلة استرداد أخرى. ماذا يحدث؟","options":["يمكن للدعم الفني إعادة تعيينها لك","قد تفقد الوصول نهائياً","تستعيدها المنصة تلقائياً"],"answer":1,"why":"في الحفظ الذاتي أنت من يحمل المفاتيح. بدون العبارة أو وسيلة صالحة أخرى، لا يستطيع أحد استردادها لك."},"transcript":[{"t":0.25,"who":"sam","text":"تعطل هاتفي. هل ضاعت عملاتي معه أيضاً؟"},{"t":9.25,"who":"nexubo","text":"عملاتك ليست مخزنة داخل هاتفك. المحفظة تتيح لك رؤية أصولك على البلوكشين وتستخدم مفاتيح للموافقة على العمليات. الاسترداد يعتمد على نوع المحفظة وطريقة النسخ الاحتياطي التي احتفظت بها."},{"t":32.25,"who":"narrator","text":"في حساب المنصة الاحتجازي، تدير المنصة الأصول والمفاتيح وتعمل أنت عبر حسابك. وفي محفظة الحفظ الذاتي، تتحكم أنت ببيانات الاعتماد. تختلف السهولة والمسؤولية بينهما."},{"t":60.25,"who":"sam","text":"إذا نسيت كلمة المرور في أي منهما، هل تتصل بالدعم الفني فحسب؟"},{"t":63.86,"who":"nexubo","text":"لا تفكر بهذه الطريقة. في محفظة عبارة الاسترداد القياسية، إذا فقدت العبارة ولا تملك طريقة بديلة، فلن يتمكن الدعم من استعادتها لك."},{"t":84.25,"who":"nexubo","text":"الاحتفاظ بالأصول على المنصة ينطوي على مخاطر المنصة. وحفظها بنفسك قد يفشل بسبب تسريب المفتاح أو توقيع معاملة خاطئة. اليوم، افهم الفرق فقط دون تسرع."},{"t":103.25,"who":"narrator","text":"من يتحكم في صلاحية تحريك الأصول؟ أجب عن ذلك أولاً، ثم حدد نوع الحساب أو المحفظة التي تحتاجها."},{"t":116.25,"who":"narrator","text":"بابان يبدوان متطابقين، أحدهما مزيف. في الحلقة القادمة: كيف تكتشف الباب الحقيقي."},{"t":121.75,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":4,"title":"ابحث عن الباب الحقيقي: لا تفتح حساباً على عماك","goal":"فحص النطاق الرسمي ومتطلبات منطقتك وتفعيل الأمان الأساسي قبل التسجيل.","task":"ابحث عن الاختلاف في شريط العنوان على صفحة تسجيل تجريبية.","answer":"اسم النطاق الرسمي غير متطابق. لا تُدخل أي بيانات في مواقع مشبوهة.","takeaways":["تحقق أولاً من أن المنصة تخدم بلدك الفعلي قبل أي شيء آخر.","سجّل فقط عبر المدخل الرسمي المؤكد، باستخدام بريدك الإلكتروني أو هاتفك الخاص.","بعد التسجيل مباشرة، فعّل ميزات الأمان واحفظ خيارات الاسترداد."],"quiz":{"q":"ما الذي يجب أن تتأكد منه أولاً قبل التسجيل؟","options":["حجم مكافأة الترحيب","أن المنصة تخدم بلدك وأن المدخل رسمي","عدد متابعي المنصة"],"answer":1,"why":"الأهلية والمدخل الرسمي يأتيان أولاً. لا ينبغي للمكافأة أن تحدد أين تفتح حسابك."},"transcript":[{"t":0.25,"who":"sam","text":"بحثت عن 'منصة تداول' وظهرت عشرة روابط متشابهة. أي منها هو الحقيقي؟"},{"t":9.25,"who":"nexubo","text":"لا تنقر عشوائياً. قبل التسجيل، تحقق من أربعة أمور: النطاق الرسمي، متطلبات منطقتك، المنتجات المتاحة، وأمان حسابك."},{"t":32.25,"who":"narrator","text":"بعد التأكد من المدخل الرسمي، سجل ببريدك الإلكتروني أو هاتفك الشخصي، وعيّن كلمة مرور فريدة وأكمل التحقق المطلوب. لا تشترِ حسابات الآخرين أبداً ولا تزور هويتك."},{"t":60.25,"who":"nexubo","text":"التسجيل ليس الخطوة الأخيرة. فعّل ميزات الأمان المتاحة، وتحقق من الأجهزة المسجلة، واحفظ خيارات الاسترداد. لا ترسل رمز التحقق لمرة واحدة أبداً لأي مدّعٍ للدعم."},{"t":84.25,"who":"narrator","text":"موقعنا يساعدك في البحث عن المعلومات، لكن علاقة الشراكة ليست ضماناً للأمان. إذا لم تكن البيانات مؤكدة، فلا تبدأ عملية التسجيل."},{"t":103.25,"who":"sam","text":"توقف. تأكد من الأهلية والشروط أولاً."},{"t":107.02,"who":"nexubo","text":"صحيح. تعرّف على الباب الحقيقي أولاً، ثم افتح الحساب."},{"t":127.35,"who":"narrator","text":"افعل ذلك الآن: فعّل التحقق بخطوتين. في الحلقة القادمة: شخص في المحادثة يعرض 'إجراء التوثيق KYC نيابة عنك'."},{"t":134.45,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":5,"title":"كيف يعمل توثيق الهوية KYC، ولمن يجب تقديم مستنداتك؟","goal":"فهم الغرض العام ومسار التحقق من الهوية، وتقديمها فقط عبر القنوات الرسمية المعتمدة.","task":"رتب خطوات التحقق باستخدام بيانات وهمية. يمنع منعاً باتاً رفع مستندات حقيقية في الدورة.","answer":"التحقق من الرابط الرسمي ← إرسال بياناتك الحقيقية حسب متطلبات منطقتك ← الانتظار والتحقق من النتيجة.","takeaways":["يؤكد KYC أنك صاحب الحساب، ويساعد المنصة على الالتزام بالقواعد.","قدّم هويتك فقط داخل مسار التحقق الرسمي، ولا ترسلها أبداً في محادثة.","إذا فشل التحقق، اقرأ السبب وصحّحه وأعد المحاولة بهويتك الحقيقية."],"quiz":{"q":"من يجب أن يستلم وثيقة هويتك؟","options":["\"وكيل\" متعاون في مجموعة دردشة","مسار التحقق الرسمي الموثّق فقط","دردشة الدورة، ليتحقق منها الآخرون"],"answer":1,"why":"المسار الرسمي فقط. NexuAlpha لا تطلب هويتك أبداً، ولا ينبغي لأي غريب أن يطلبها."},"transcript":[{"t":0.25,"who":"sam","text":"يطلبون وثيقة هويتي. وهذا الشخص يقول إنه يستطيع إتمام ذلك بالنيابة عني؟"},{"t":9.25,"who":"nexubo","text":"التحقق من الهوية يهدف لتأكيد ملكيتك للحساب والامتثال للأنظمة. تأكد أولاً أنه مسار رسمي، ولا تسلم وثائقك أو رموزك لأي 'وسيط' في مجموعات الدردشة."},{"t":32.25,"who":"narrator","text":"عادة ما تدخل بياناتك الحقيقية، وترفع وثيقة صالحة مقبولة، ثم تتبع التعليمات لالتقاط صورة أو فحص الوجه. الوثائق المطلوبة تعتمد على منطقتك والمنصة."},{"t":60.25,"who":"nexubo","text":"إذا فشل التحقق، اقرأ السبب أولاً: هل انتهت صلاحية الوثيقة؟ هل هناك انعكاس ضوئي؟ هل الاسم متطابق؟ صحح الخطأ حسب الإرشادات ولا تحاول بهوية مزيفة."},{"t":84.25,"who":"sam","text":"بمجرد الانتهاء، هل يمكنني التداول على الفور؟"},{"t":86.78,"who":"nexubo","text":"ليس مضموناً. النتيجة والمنتجات المتاحة والإيداع تعتمد على الإشعار الرسمي. وهذه الأكاديمية لا تجمع وثائق هويتك الحقيقية أبداً."},{"t":103.25,"who":"narrator","text":"لمن تقدم وثيقة هويتك؟ للمسار الرسمي المعتمد فقط. ليس لنا، وليس لشخص غريب."},{"t":127.25,"who":"narrator","text":"إيداع، شراء، تحويل: ثلاثة أزرار تبدو متماثلة. في الحلقة القادمة: أي زر يجب الضغط عليه."},{"t":132.85,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":6,"title":"الإيداع الأول: من أين تأتي الأموال وأين تستقر؟","goal":"التمييز بين الإيداع بالعملات المحلية، الشراء المباشر، إيداع الكريبتو، والتحويل الداخلي؛ والتحقق من القنوات والرسوم.","task":"طابق بين ثلاثة سيناريوهات: إيداع بنكي بالعملة المحلية، إيداع كريبتو متاح، وتحويل داخلي بين الحسابات.","answer":"مسارات مختلفة بقواعد ورسوم وأوقات متفاوتة. التحويل الداخلي لا يستخدم البلوكشين.","takeaways":["إيداع العملة الورقية وشراء العملات المشفرة والإيداع على السلسلة والتحويل الداخلي مسارات مختلفة.","الإيداع على السلسلة يحتاج إلى عملة وشبكة مدعومتين؛ أما التحويل الداخلي فيبقى داخل المنصة.","لا تدفع أبداً لغريب خارج المنصة؛ وتحقق أولاً من المكان الذي سيصل إليه الرصيد."],"quiz":{"q":"نقلت USDT من حساب التمويل إلى حساب التداول على المنصة نفسها. ما هذا؟","options":["إيداع على السلسلة","تحويل داخلي","إيداع بالعملة الورقية"],"answer":1,"why":"إنه ينقل الرصيد بين حساباتك أنت فقط. وعادةً لا يكون تحويلاً على السلسلة."},"transcript":[{"t":0.25,"who":"sam","text":"هناك ثلاثة أزرار: إيداع، شراء، وتحويل. أليست جميعها مخصصة لإدخال الأموال؟"},{"t":9.25,"who":"nexubo","text":"لا، فهي تحرك أصولاً مختلفة. هل تودع عملة محلية أم تنقل كريبتو تملكه بالفعل؟ أم تنقل الرصيد بين حساباتك الداخلية فقط؟"},{"t":32.25,"who":"narrator","text":"الإيداع النقدي يضيف رصيداً نقدياً لحسابك. والشراء المباشر يعني الدفع واستلام الكريبتو فوراً. تختلف قنوات البنوك والبطاقات والرسوم والحدود حسب المنصة."},{"t":60.25,"who":"nexubo","text":"إذا كنت تملك كريبتو بالفعل، يمكنك إيداعه عبر عملة وشبكة مدعومتين. التحويل الداخلي ينقل الرصيد بين حساباتك دون بلوكشين. تأكد أين سيستقر الرصيد أولاً."},{"t":84.25,"who":"narrator","text":"توفر بعض المنصات التداول بين المستخدمين (P2P). هذا ليس اسماً بديلاً للتحويل البنكي. لا تدفع خارج المنصة بشكل خاص، وتجنب الأموال مجهولة المصدر."},{"t":103.25,"who":"sam","text":"لا، إنها قنوات مختلفة."},{"t":105.59,"who":"nexubo","text":"صحيح. انظر إلى نوع الأصل أولاً، ثم المسار، وأخيراً تحقق مما وصل فعلياً."},{"t":116.25,"who":"narrator","text":"BTC/USDT: هل تعني هذه الشرطة المائلة أنك تشتري عملتين؟ في الحلقة القادمة: أول صفقة تداول فوري لك."},{"t":122.45,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":7,"title":"صفقتك الأولى في التداول الفوري: من 100 إلى 0.002 BTC","goal":"إتمام عملية شراء تجريبية في السوق الفوري بمبلغ وكمية ورسوم واضحة.","task":"برصيد افتراضي قدره 1,000، اشترِ 0.002 BTC. تحقق من رصيد USDT المتبقي البالغ 899.90 وسجل الصفقة.","answer":"المبلغ 100، الرسوم 0.10، إجمالي المصروف 100.10؛ المتبقي 899.90.","takeaways":["BTC/USDT تعني البيتكوين مسعّراً بـ USDT: تدفع USDT وتستلم بيتكوين.","تحقق مما إذا كانت خانة الطلب تطلب مبلغاً من المال أم عدداً من العملات.","بعد الشراء، راجع سجل الصفقة: حالة التنفيذ ومتوسط السعر والرسوم."],"quiz":{"q":"اشتريت 0.002 BTC عند سعر 50,000 مع رسوم 0.1% تُخصم بشكل منفصل بـ USDT. ما إجمالي ما أنفقته؟","options":["100","100.10","110"],"answer":1,"why":"100 ثمن العملات زائد رسوم 0.10 يساوي 100.10."},"transcript":[{"t":0.25,"who":"sam","text":"هذه الشرطة المائلة. هل يجب أن أشتري كلتا العملتين؟"},{"t":9.25,"who":"nexubo","text":"لا. هذا يعني أن البيتكوين مسعر بعملة USDT. عند الشراء، تدفع USDT وتستلم بيتكوين. وعند البيع، العكس بالعكس."},{"t":35.25,"who":"narrator","text":"نتدرب بحساب افتراضي. تأكد أنه تداول فوري spot وليس عقوداً futures. اختر الزوج، حدد 'شراء'، ثم أدخل المبلغ. وتأكد إن كان الحقل يطلب مبلغاً نقدياً أم كمية عملات."},{"t":67.25,"who":"nexubo","text":"لنفترض أن سعر التنفيذ 50,000 وأنفقت 100. ستحصل على 0.002 بيتكوين. مع افتراض رسم 0.1% يخصم منفصلاً من USDT، يصبح إجمالي الإنفاق 100.10. القواعد الحقيقية تحددها المنصة."},{"t":95.25,"who":"sam","text":"إذن بمجرد الضغط على 'شراء' أكون قد امتلكت العملات حتماً؟"},{"t":99.07,"who":"nexubo","text":"تحقق من سجل التداول أيضاً. هناك فرق بين غير منفذ، ومنفذ جزئياً، ومنفذ بالكامل. تحقق أيضاً من السعر المتوسط الفعلي والرسوم."},{"t":116.25,"who":"narrator","text":"تدريبك الأول ليس لتخمين الصعود أو الهبوط، بل للتحقق من هذه الأمور الخمسة. وعند الانتهاء، لا بأس في التريث قبل أي تداول حقيقي."},{"t":140.95,"who":"narrator","text":"لنفترض أن السعر ارتفع وقمت بالبيع. فلماذا لم يتغير رصيدك البنكي؟ نوضح ذلك في الحلقة القادمة."},{"t":146.85,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":8,"title":"لقد قمت بالبيع. فلماذا لم تصل الأموال إلى حسابي البنكي؟","goal":"التمييز بين بيع الأصل، والحصول على رصيد عملة مستقرة أو نقدية، والسحب البنكي الفعلي.","task":"أكمل عملية بيع تجريبية، ثم حدد على مخطط تدفق الأموال الخطوة التي تمثل السحب البنكي.","answer":"البيع مقابل USDT ليس سحباً بنكياً. صافي نتيجة التداول في هذا المثال: 9.79.","takeaways":["البيع مقابل USDT يمنحك رصيداً من USDT، لا مالاً في بنكك.","البيع والسحب إلى بنكك خطوتان منفصلتان.","السعر الأعلى ليس ربحك الصافي: اطرح كل الرسوم أولاً."],"quiz":{"q":"بعت البيتكوين مقابل USDT. أين المال الآن؟","options":["في حسابك المصرفي","كرصيد USDT على المنصة","تم تحويله بالفعل إلى عملتك المحلية"],"answer":1,"why":"لقد استلمت USDT. إيصال المال إلى بنكك خطوة سحب منفصلة."},"transcript":[{"t":0.25,"who":"sam","text":"لقد قمت بالبيع بالتأكيد. فلماذا لم يستلم حسابي البنكي الأموال حتى الآن؟"},{"t":9.25,"who":"nexubo","text":"تحقق من زوج التداول الذي بعت فيه. إذا بعت مقابل USDT، فقد حصلت على رصيد USDT وليس تحويلاً بنكياً. البيع والسحب إلى البنك خطوتان منفصلتان."},{"t":35.25,"who":"narrator","text":"نفس المثال التعليمي. تبيع 0.002 بيتكوين بسعر 55,000، أي 110. بخصم رسم افتراضي 0.11، يستقر 109.89 في حسابك."},{"t":67.25,"who":"sam","text":"إذن ربحت عشرة؟"},{"t":68.76,"who":"nexubo","text":"اطرح التكاليف. هنا الناتج 9.79، قبل احتساب رسوم تحويل العملات أو السحب المحتملة. ارتفاع السعر لا يعني ربحك الصافي النهائي."},{"t":95.25,"who":"narrator","text":"إذا كنت بحاجة للأموال في حسابك البنكي، فتحقق أولاً من دعم منطقتك. ثم اسحب عبر المسار الرسمي لحساب باسمك الشخصي. راجع الاسم، المبلغ المستلم، الرسوم، وشروط المعالجة."},{"t":116.25,"who":"sam","text":"لا."},{"t":116.98,"who":"nexubo","text":"احتفظ بسجلات تداولاتك وسحوباتك. إذا لم تكن متأكداً من طبيعة الرصيد، فلا تعتمد على إشعار 'نجاح' واحد."},{"t":131.25,"who":"narrator","text":"شبكة أرخص قليلاً. نقرة واحدة خاطئة. قد لا تصل عملاتك أبداً. في الحلقة القادمة: فحوصات لا يجوز التخمين فيها أبداً."},{"t":137.95,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":9,"title":"قبل التحويل: لا تخمّن أي خطوة من هذه الخطوات","goal":"التحقق من العملة والشبكة والعنوان والمذكرة وشروط الوصول، وإرسال تجربة صغيرة أولاً.","task":"في نموذج سحب تجريبي يحتوي على أخطاء متعمدة، صحح عدم تطابق الشبكة والمذكرة المفقودة؛ ثم أرسل تجربة صغيرة افتراضية.","answer":"لا ترسل إلا بعد تطابق جميع الشروط الأساسية. لا توجد حماية افتراضية باسم 'التحويل التلقائي للشبكة الصحيحة'.","takeaways":["تأكد من العملة والشبكة اللتين يدعمهما المستلم قبل الإرسال.","انسخ العنوان من صفحة الاستلام، وتحقق منه كاملاً، وأضف أي مذكرة (memo) أو وسم (tag).","أرسل مبلغاً تجريبياً صغيراً أولاً وتأكد من إضافته إلى الرصيد."],"quiz":{"q":"صفحة الاستلام تطلب مذكرة (memo). ماذا تفعل؟","options":["تتجاهلها، فالعنوان يكفي","تكتب المذكرة تماماً كما هي معروضة","تستخدم مذكرة من تحويل قديم"],"answer":1,"why":"إذا كانت المذكرة أو الوسم مطلوبين، فقد لا يُضاف التحويل إلى الرصيد بدونهما."},"transcript":[{"t":0.25,"who":"sam","text":"هذه الشبكة أرخص. لمَ لا أبدل إليها ببساطة؟"},{"t":9.25,"who":"nexubo","text":"تأكد أولاً من الأصل والشبكة التي يدعمها المستلم. ثم فكر بالرسوم. إذا لم يتطابق الطرفان، فلا ترسل لمجرد أنها أرخص. حتى USDT توجد على شبكات مختلفة."},{"t":39.25,"who":"narrator","text":"اعتبر الشبكة هي المسار والعنوان هو الوجهة. لكن عنوانين قد يتشابهان دون أن يعملا على نفس الشبكة. تحقق دائماً من دعم منصة الاستلام لهذه السلسلة وهذا الأصل."},{"t":75.25,"who":"nexubo","text":"انسخ العنوان من صفحة الاستلام وتحقق منه بالكامل. املأ المذكرة memo أو الوسم tag إذا طُلب ذلك. تأكد من الحد الأدنى للإيداع ورسوم السحب والمبلغ الصافي. لا تعتمد على أول وآخر أحرف فقط."},{"t":106.25,"who":"narrator","text":"أرسل تجربة صغيرة تستوفي الحد الأدنى وتأكد من قيدها في الحساب. وفي التحويلات الأكبر، أعد التحقق من كل شيء ولا تعتمد على السجلات القديمة. وفي محافظ الحفظ الذاتي، جهز رسوم الشبكة."},{"t":130.25,"who":"sam","text":"لا."},{"t":131.16,"who":"nexubo","text":"التحقق مرة إضافية قبل الإرسال أهم بكثير من البحث عن مساعدة بعد فوات الأوان."},{"t":146.25,"who":"narrator","text":"تظهر الرسالة 'نجاح' لكن لم يصل شيء. لا ترسل مجدداً. في الحلقة القادمة: أين تبحث."},{"t":151.65,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":10,"title":"يظهر أنه تم الإرسال لكنه لم يصل. أين تبحث عن المشكلة؟","goal":"التمييز بين معالجة المرسل، والتأكيد على البلوكشين، وقيد الرصيد لدى المستلم، ومعرفة مسارات المعالجة المتاحة.","task":"طابق بين ثلاثة سيناريوهات للأعطال مع: جهة الإرسال، حالة البلوكشين، وجهة الاستلام.","answer":"حدد الحالة أولاً ثم تواصل مع القناة الرسمية المناسبة. ولا تكرر الدفع إذا كان السبب مجهولاً.","takeaways":["\"تم الإرسال\" و\"على السلسلة\" و\"تمت الإضافة إلى الرصيد\" ثلاث محطات مختلفة.","استخدم معرّف المعاملة (hash) في مستكشف الكتل الخاص بالشبكة الصحيحة.","شارك السجلات مع الدعم الرسمي، ولا تشارك أبداً عبارة الاسترداد أو المفتاح الخاص أو الرموز."],"quiz":{"q":"يظهر تحويلك بحالة \"تم الإرسال\" لكنه لم يصل. ما الخطوة الأولى؟","options":["إرسال المبلغ نفسه مرة أخرى","تحديد مكان توقفه باستخدام السجل ومعرّف المعاملة","الدفع لشخص يَعِد باسترداده"],"answer":1,"why":"حدّد المحطة أولاً، ثم تواصل مع القناة الرسمية المناسبة. لا تواصل الإرسال."},"transcript":[{"t":0.25,"who":"sam","text":"لم يصل. هل أرسل عدة دفعات أخرى للتجربة؟"},{"t":9.25,"who":"nexubo","text":"لا ترسل مجدداً. فالمعاملة المرسلة، والمؤكدة على الشبكة، والمقيدة في الحساب ليست شيئاً واحداً. حدد المحطة التي تعثر فيها التحويل أولاً قبل أن تتواصل مع أي جهة."},{"t":32.25,"who":"narrator","text":"احتفظ بسجل الإرسال. إذا كان لديك هاش المعاملة، فتحقق منه عبر مستكشف البلوكشين الرسمي لتلك الشبكة: الحالة، العنوان، والمبلغ. ولا تخلط نتائج سلسلة أخرى."},{"t":60.25,"who":"nexubo","text":"قد تتطلب منصة الاستلام تأكيدات إضافية أو مراجعة داخلية. إذا أخطأت في العملة أو الشبكة أو العنوان أو المذكرة، فتوقف عن الإرسال وقدم الحقائق للدعم الرسمي."},{"t":84.25,"who":"narrator","text":"لا يمكن التراجع عن المعاملة المكتملة على البلوكشين كأي إجراء عادي. إمكانية الاسترداد تعتمد على الشروط التقنية والمنصة، ولا يوجد ضمان. لا تصدق من يزعم استردادها بمقابل مالي."},{"t":103.25,"who":"sam","text":"قدّم السجلات المطلوبة فقط. وإياك وإعطاء عبارة الاسترداد أو المفتاح الخاص أو الرموز."},{"t":107.92,"who":"nexubo","text":"صحيح. حدد مكان العطل أولاً، ولا تكرر الإرسال بعشوائية."},{"t":116.25,"who":"narrator","text":"'مرحباً، أنا من الدعم الفني. أرسل لي عبارة الاسترداد الخاصة بك.' في الحلقة القادمة: ما الذي يريده المحتالون حقاً."},{"t":122.45,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":11,"title":"شخص يدعي أنه سيجعلك تكسب المال. انظر أولاً ماذا يطلب منك.","goal":"التعرف على طلبات البيانات السرية، المدفوعات خارج المنصة، التراخيص المشبوهة، والوعود بأرباح مضمونة.","task":"اكتشف الطلبات الخطيرة في أربع محادثات افتراضية، واختر مسار 'التوقف والتحقق رسمياً'.","answer":"إذا طلب منك أي شخص مفتاحك الخاص أو عبارة الاسترداد أو الرموز أو موافقة غامضة، فلا تستجب له أبداً.","takeaways":["عبارة الاسترداد والمفتاح الخاص مفاتيح تحكّم، وليست رموزاً للدعم الفني.","العوائد المضمونة والضغط عليك للدفع علامات خطر.","لا تؤكد أبداً توقيعاً أو موافقة لا تفهمها."],"quiz":{"q":"أيّ مما يلي آمن مشاركته لكي تستلم دفعة؟","options":["عنوانك العام","عبارة الاسترداد","رمز يُستخدم مرة واحدة"],"answer":0,"why":"العنوان العام مخصص للاستلام. أما الأسرار والرموز فتمنح التحكم لغيرك."},"transcript":[{"t":0.25,"who":"sam","text":"يقول إنه من الدعم الفني ويريد مساعدتي في ترقية المحفظة."},{"t":9.25,"who":"nexubo","text":"في المحفظة القياسية، عبارة الاسترداد هي مفتاح التحكم الكامل وليست رمز دعم. وكذلك مفتاحك الخاص. لا ترسلها لأي أحد إطلاقاً، حتى مساعد أكاديميتنا لا يجوز له طلبها."},{"t":32.25,"who":"narrator","text":"علامتان خطيرتان أخريان: الأرباح المضمونة، والضغط للدفع السريع. لقطة شاشة لأرباح ضخمة لا تثبت شيئاً. إذا استعجلك شخص لتجاوز خطوات الفحص العادية، فتوقف فوراً."},{"t":60.25,"who":"nexubo","text":"ربط المحفظة، وتوقيع رسالة، والموافقة على الوصول لأصولك أمور مختلفة تماماً. إذا لم تفهم التوقيع أو التصريح فلا تؤكده. عدم طلب كلمة المرور لا يعني انعدام الخطر."},{"t":84.25,"who":"narrator","text":"إذا شككت في تسريب بياناتك، فتوقف فوراً واستخدم قنوات الأمان الرسمية. اتخذ إجراءات محددة لما تسرب فعلاً، ولا تثبت أبداً برامج تحكم عن بُعد بناءً على طلب أي شخص."},{"t":103.25,"who":"sam","text":"مشاركة معلومات الاستلام لا تعني التنازل عن مفاتيح التحكم."},{"t":106.72,"who":"nexubo","text":"لا تشارك الأسرار. لا توافق على ما لا تفهمه. لا تدع أحداً يستعجلك للدفع."},{"t":116.25,"who":"narrator","text":"انتهت إحدى عشرة حلقة. هل حان وقت إيداع أموال حقيقية؟ ختام الموسم 1 يحمل إجابة مفاجئة."},{"t":123.15,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":12,"title":"ختام الموسم 1: يمكنك القيام بذلك، ولديك خيار عدم التداول","goal":"إكمال التدريب الشامل، وفهم أن عدم التداول خيار مشروع وصحيح، ومعرفة الخطوات التالية.","task":"أجب عن الأسئلة الثلاثة الختامية للدورة في لوحة التدريب.","answer":"البيع مقابل USDT ليس سحباً بنكياً؛ التأكيد بالبلوكشين ليس قيداً بالحساب؛ لا تشارك بيانات الاعتماد ولا تحول عند الشك.","takeaways":["الهدف هو مسار صحيح: المدخل والأهلية، ثم السوق الفوري، ثم المبلغ والرسوم، ثم السجل.","إيقاف تحويل غير واضح إجابة صحيحة أيضاً.","شهادتك سجلّ تعلّم، وليست ترخيصاً للاستثمار."],"quiz":{"q":"يظهر في تحويل تدريبي شبكة خاطئة. ما التصرف الصحيح؟","options":["الإرسال على أي حال والأمل بالأفضل","التوقف وعدم الإرسال","التبديل إلى مبلغ أكبر"],"answer":1,"why":"عندما تكون الشبكة أو الرسوم أو الهوية غير واضحة، فالتوقف أهم من إنهاء المهمة."},"transcript":[{"t":0.25,"who":"sam","text":"أتممت جميع الدروس. هل يعني هذا أنني جاهز للتداول الحقيقي الآن؟"},{"t":9.25,"who":"nexubo","text":"تمهل. اليوم سنخوض تدريباً افتراضياً شاملاً. تحقق من المدخل، والسوق الفوري spot، والمبلغ والرسوم، وسجل الصفقة. إذا كان لديك شك، فلا تتداول."},{"t":39.25,"who":"narrator","text":"تكون إجابتك صحيحة عندما تدرك المخاطر وتتحقق بهدوء. النقاط لا تعني أرباحاً مستقبلية مضمونة. إذا أخطأت، فعد إلى الدرس المخصص وراجعه."},{"t":75.25,"who":"sam","text":"هناك خطأ ما في بيانات هذا التحويل. لن أرسله."},{"t":78.5,"who":"nexubo","text":"هذه أيضاً إجابة صحيحة تماماً. عندما تكون الشبكة أو الرسوم أو الهوية غير واضحة، فإن التوقف أهم بكثير من المضي قدماً في المعاملة."},{"t":106.25,"who":"narrator","text":"أخيراً، كرر ثلاث حقائق: أين ذهب الأصل؟ كم المبلغ المخصوم فعلياً؟ ومن يتحكم بحسابك؟ إن لم تكن متأكداً من إحداها، فعد لتلك الحلقة وتدرب مجدداً."},{"t":130.25,"who":"nexubo","text":"ما اكتسبته هو سجل تعليمي وليس رخصة استثمار. مواصلة التعلم أو الامتناع عن التداول حالياً كلاهما خيار سليم. افهم أولاً، ثم تصرّف."},{"t":157.55,"who":"narrator","text":"الموسم 2: السعر الظاهر على شاشتك ليس دائماً ما تدفعه في النهاية. اكتشف السبب."},{"t":163.05,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":13,"title":"لماذا لا يطابق السعر على الشاشة سعر تنفيذ صفقتي؟","goal":"فهم دفتر الأوامر، وفارق السعر بين العرض والطلب، وعمق السوق، والرسوم، والانزلاق السعري.","task":"طابق 0.002 BTC مقابل مستويين من أوامر البيع الافتراضية واحسب المتوسط المرجح للسعر.","answer":"الإجمالي 100.10، المتوسط 50,050 قبل الرسوم التعليمية. ومع رسم 0.1% بعملة USDT: الرسم 0.1001، الإجمالي 100.2001 (دون تقريب مسبق).","takeaways":["آخر سعر هو سعر أحدث صفقة، وليس عرضاً متاحاً لأي حجم.","الطلبات الأكبر قد تُنفّذ عبر عدة مستويات في دفتر الطلبات.","الانزلاق السعري ورسوم التداول تكلفتان منفصلتان: راجع الفاتورة."],"quiz":{"q":"نُفّذ نصف الـ 0.002 BTC عند 50,000 والنصف الآخر عند 50,100. ما متوسط سعرك؟","options":["50,000","50,050","50,100"],"answer":1,"why":"متوسط نصفين متساويين هو 50,050. والرسوم تكلفة منفصلة تُضاف فوقه."},"transcript":[{"t":0.25,"who":"sam","text":"كان السعر هكذا قبل ثانية واحدة. لماذا تختلف فاتورتي الآن؟"},{"t":9.25,"who":"nexubo","text":"السعر الأخير على الشاشة هو سجل لأحدث صفقة تمت، وليس عرضاً لكمية غير محدودة. الكميات المعروضة للبيع والشراء الآن مسجلة في دفتر الأوامر."},{"t":32.25,"who":"narrator","text":"لنفترض أنك تشتري 0.002 بيتكوين. المستوى الأول يحتوي على نصف الكمية فقط. النصف الآخر ينفذ بسعر أعلى. المتوسط يصبح 50,050 وليس 50,000."},{"t":60.25,"who":"nexubo","text":"الانزلاق السعري هو الفارق بين السعر المتوقع والسعر المنفذ فعلياً. ليس دائماً ضدك. أما رسوم التداول فهي تكلفة منفصلة. لا تخلط بينهما تحت شعار 'تداول مجاني'."},{"t":84.25,"who":"narrator","text":"الأوامر الكبيرة، أو ضعف عمق السوق، أو تقلب الأسعار السريع تزيد من احتمال انحراف السعر عن توقعاتك. راقب الحجم والعمق قبل الطلب، ومتوسط السعر الفعلي بعده."},{"t":103.25,"who":"sam","text":"لا."},{"t":104.04,"who":"nexubo","text":"لا تعرف تفاصيل تنفيذك إلا عندما ترى الفاتورة النهائية. لا تركز فقط على الرقم الأكبر على الشاشة."},{"t":126.75,"who":"narrator","text":"وضعت أمر شراء ولم يحدث شيء. هل تعطل النظام؟ في الحلقة القادمة: أمر السوق، الأمر المحدد، والإلغاء."},{"t":132.45,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":14,"title":"السوق، الحد، الإلغاء: ما الذي يحلّه كل منها؟","goal":"اختيار الأمر حسب 'أولوية التنفيذ' أو 'أولوية حد السعر'، وفهم الأوامر غير المنفذة والمنفذة جزئياً.","task":"ضع أمر حد افتراضياً، وراقب التنفيذ الجزئي، ثم ألغِ الكمية المتبقية.","answer":"حتى مع ملاءمة السعر، يتأثر التنفيذ بالكمية المتاحة؛ ولا يمكن التراجع عن الأجزاء المنفذة بالإلغاء.","takeaways":["أمر السوق يُنفّذ بسرعة بالأسعار المتاحة الآن؛ وقد يتغير السعر النهائي.","الأمر المحدد يضع سقفاً لسعرك، لكنه قد لا يُنفّذ.","الإلغاء يؤثر فقط في الجزء غير المنفّذ؛ وما نُفّذ يبقى."],"quiz":{"q":"نُفّذ نصف أمرك المحدد ثم ألغيته. ماذا يحدث؟","options":["يُعكس كل شيء","يُلغى النصف غير المنفّذ فقط","يتحول النصف المنفّذ إلى أمر سوق"],"answer":1,"why":"الإلغاء لا يمكنه التراجع عن تنفيذ تم. إنه يوقف الكمية المتبقية فقط."},"transcript":[{"t":0.25,"who":"sam","text":"لقد ضغطت على شراء. لماذا لم يُنفّذ الأمر بعد؟"},{"t":9.25,"who":"nexubo","text":"تميل أوامر السوق إلى التنفيذ بأسرع ما يمكن بالأسعار المتاحة حالياً، ولكن السعر النهائي قد يتغير. تحدد أوامر الحد ألا يتجاوز الشراء أو يقل البيع عن سعر معين، دون ضمان التنفيذ."},{"t":32.25,"who":"narrator","text":"إذا أردت الشراء بسعر أقل من السعر الحالي، فقد تحتاج إلى الانتظار. وعلى العكس، إذا استوفى أمر الحد عروض الطرف المقابل، فقد يُنفّذ على الفور؛ فليس كل أمر حد محكوماً عليه بالانتظار في الطابور."},{"t":60.25,"who":"sam","text":"هل يعني إلغاء الأمر التراجع عما اشتريته للتو أيضاً؟"},{"t":62.82,"who":"nexubo","text":"لا. يتعامل الإلغاء فقط مع الجزء الذي لم يُنفّذ بعد؛ أما ما تم تنفيذه بالفعل فلا يمكن التراجع عنه."},{"t":84.25,"who":"narrator","text":"تحقق من الحالة بوضوح قبل التصرف. فإن تصنيفك كصانع أو آخذ يعتمد على كيفية التنفيذ الفعلي؛ واختيار أمر الحد لا يضمن الحصول على معدل رسوم معين."},{"t":103.25,"who":"sam","text":"كلا."},{"t":104.12,"who":"nexubo","text":"اختيار الأمر هو اختيار لطريقة التنفيذ، وليس تمنياً."},{"t":116.25,"who":"narrator","text":"هل تعني الشمعة الخضراء أن الشمعة التالية سترتفع أيضاً؟ في الحلقة القادمة."},{"t":121.05,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":15,"title":"شمعة واحدة: ما هي الأشياء الأربعة التي تخبرك بها؟","goal":"قراءة سعر الافتتاح والأعلى والأدنى والإغلاق والإطار الزمني؛ وعدم التعامل مع اللون أو الشكل الفردي كتنبؤ.","task":"انقر على الافتتاح والأعلى والأدنى والإغلاق في الشمعة الافتراضية وأكد الإطار الزمني للرسم البياني.","answer":"50,000 / 51,000 / 49,000 / 50,500؛ إطار خمس دقائق.","takeaways":["الشمعة الواحدة تعرض أربعة أسعار لفترة واحدة: الافتتاح والأعلى والأدنى والإغلاق.","اقرأ الإطار الزمني قبل الشكل: خمس دقائق ليست يوماً.","تختلف الألوان بين التطبيقات، والشمعة الواحدة سجلّ وليست توقعاً."],"quiz":{"q":"شمعة خمس دقائق تفتتح عند 50,000، وتصل إلى 51,000، وتنخفض إلى 49,000، وتغلق عند 50,500. ما أعلى سعر؟","options":["50,500","51,000","49,000"],"answer":1,"why":"قمة الظل العلوي هي أعلى سعر في تلك الفترة: 51,000."},"transcript":[{"t":0.25,"who":"sam","text":"أخضر، هل يعني أنه سيرتفع في الثانية التالية؟"},{"t":9.25,"who":"nexubo","text":"تسجل الشمعة أربعة أسعار لفترة زمنية محددة: الافتتاح والأعلى والأدنى والإغلاق. هذه حركة افتراضية لخمس دقائق، وليست ضماناً للخمس دقائق القادمة."},{"t":32.25,"who":"narrator","text":"يساعدك جسم الشمعة على رؤية الفرق بين الافتتاح والإغلاق، وتحدد الظلال أعلى وأدنى نقطة تم الوصول إليها. والشمعة التي لم تنتهِ بعد ستستمر في التغير مع الصفقات الجديدة."},{"t":60.25,"who":"sam","text":"لماذا يبدو الرسم البياني مختلفاً عند تبديل الإطار الزمني؟"},{"t":63.75,"who":"nexubo","text":"تغيرت الفترة الزمنية التي تمثلها كل شمعة. اقرأ الإطار الزمني أولاً قبل الحديث عن الشكل؛ ولا تعامل الخمس دقائق كما لو كانت يوماً كاملاً."},{"t":84.25,"who":"narrator","text":"قد تستخدم التطبيقات المختلفة ألواناً متباينة للصعود والهبوط، لذا انظر إلى الدليل والأرقام. تقدم البيانات السابقة معلومات، لكن شمعة واحدة لا تضمن الحركة التالية."},{"t":103.25,"who":"sam","text":"الأعلى 51,000، والإغلاق 50,500."},{"t":108.91,"who":"nexubo","text":"اقرأ السجل أولاً، ولا تعامل السجلات كنبوءات."},{"t":116.25,"who":"narrator","text":"\"لدي 1,000، وأريد خسارة 20 فقط، فهل أشتري بكل المبلغ؟\" التالي: قرر أولاً مقدار الخسارة المحتملة."},{"t":122.35,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":16,"title":"قرر مقدار ما يمكنك تحمّل خسارته قبل أن تقرر كم ستشتري","goal":"فهم أن رصيد الحساب وحجم المركز والمخاطرة المخططة هي ثلاثة أرقام مختلفة تماماً.","task":"احسب المركز الافتراضي بناءً على سعر الدخول المحدد ومسافة وقف الخسارة وميزانية المخاطر التعليمية.","answer":"400 USDT قيمة فورية اسمية؛ 0.008 BTC؛ ويجب احتساب الرسوم وفروق التنفيذ بشكل منفصل.","takeaways":["رصيد الحساب وحجم المركز والمخاطرة المخطط لها ثلاثة أرقام مختلفة.","حدّد نقطة خروجك أولاً، ثم حدّد حجم المركز.","مع وقف خسارة عند 5% وميزانية مخاطرة قدرها 20، يكون حجم المركز نحو 400."],"quiz":{"q":"الدخول عند 50,000، والخروج المخطط عند 47,500، وتقبل خسارة 20. كم يبلغ حجم المركز تقريباً؟","options":["20","400","4,000"],"answer":1,"why":"الخروج يبعد 5%، و5% من 400 تساوي 20. والتكاليف تُضاف فوق ذلك."},"transcript":[{"t":0.25,"who":"sam","text":"لدي 1,000 وأريد خسارة 20 فقط، فهل أشتري بكل المبلغ أولاً؟"},{"t":9.25,"who":"nexubo","text":"كم تملك في الحساب، وكم تشتري في هذه الصفقة، والحد الأقصى للخسارة المخطط لها هي ثلاثة أمور مختلفة. تحتاج إلى شروط خروج واضحة أولاً لتقدير حجم المركز."},{"t":35.25,"who":"narrator","text":"انظر إلى مسألة تدريبية: الدخول عند 50,000، والخروج المخطط عند 47,500، بفارق 5%. إذا كنت تخطط لتحمل خسارة قدرها 20 متجاهلاً التكاليف، فإن حجم المركز يقارب 400."},{"t":67.25,"who":"sam","text":"إذاً 'خسارة 20 كحد أقصى' لا تعني 'شراء ما قيمته 20 فقط'؟"},{"t":70.55,"who":"nexubo","text":"صحيح. هنا انخفاض مركز بقيمة 400 بنسبة 5% يعادل 20؛ وهذه معايير تعليمية فقط."},{"t":95.25,"who":"narrator","text":"تشهد الأسواق الحقيقية انزلاقاً سعرياً وفجوات ورسوماً أو تعثراً في التنفيذ، لذا فالمخاطرة المخططة لا تعني حداً مضموناً. لا تقترض لإكمال الدورة، ولا تستخدم أموال المعيشة الأساسية في التدريب."},{"t":116.25,"who":"sam","text":"عشرون."},{"t":116.98,"who":"nexubo","text":"احسب أسوأ سيناريو يمكنك قبوله أولاً، ثم انظر ما إذا كنت بحاجة إلى هذه الصفقة أصلاً."},{"t":131.25,"who":"narrator","text":"هل يعني تعيين وقف الخسارة أنك ستخسر هذا المبلغ فقط بدقة؟ التالي: حقيقة وقف الخسارة."},{"t":137.75,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":17,"title":"جني الأرباح ووقف الخسارة خطط وليست تأميناً","goal":"فهم الفرق بين التفعيل والتنفيذ، والمخاطر المختلفة لأوامر وقف السوق ووقف الحد.","task":"قارن نتائج التدريب بين أمر وقف السوق وأمر وقف الحد في نفس الهبوط الحاد.","answer":"قد يتعرض الأول لانزلاق سعري؛ وقد لا يُنفّذ الثاني إطلاقاً. وكلاهما ليس تأميناً لحماية رأس المال.","takeaways":["وقف الخسارة ينفّذ خطة خروجك؛ وليس تأميناً.","أمر الوقف السوقي يخرج بسرعة، لكنه قد ينزلق في سوق سريعة الحركة.","أمر الوقف المحدد يضع سقفاً للسعر، لكنه قد لا يُنفّذ إطلاقاً."],"quiz":{"q":"في هبوط حاد، ماذا قد يحدث لأمر الوقف المحدد؟","options":["يُنفّذ دائماً عند سعر التفعيل","قد لا يُنفّذ إذا تجاوزه السعر بسرعة","يتحول إلى تأمين"],"answer":1,"why":"الحد يحمي سعرك، لذلك قد يبقى الأمر غير منفّذ عندما يتحرك السوق بسرعة."},"transcript":[{"t":0.25,"who":"sam","text":"لقد تم ضبط وقف الخسارة، لذا سأخسر فقط المبلغ الذي حددته، أليس كذلك؟"},{"t":9.25,"who":"nexubo","text":"وقف الخسارة هو تنفيذ لخطة خروج عند تحقق الشروط، وليس تأميناً. وتفعيل الشرط لا يعني بالضرورة التنفيذ بذلك السعر، ولا يضمن توقف الخسارة عنده بالضبط."},{"t":32.25,"who":"narrator","text":"يُنفّذ بسعر السوق بعد التفعيل، مع التركيز على الخروج السريع، لكن السعر الفعلي قد يشهد انزلاقاً سعرياً. وقد تتسع الفجوة في التحركات السريعة أو شح السيولة."},{"t":60.25,"who":"nexubo","text":"يضع أمراً محدداً بعد التفعيل، مما يضبط السعر المقبول، لكنه قد يفشل في البيع إذا انهار السعر بسرعة. لا يوجد نوع أفضل دائماً؛ إنها مقايضات مختلفة."},{"t":84.25,"who":"narrator","text":"تحقق من الاتجاه والكمية وحالة الأمر بعد الضبط. وفي العقود، تأكد من نوع سعر التفعيل لتجنب وضع وقف الخسارة عند مستوى قد يتعرض للتصفية أولاً."},{"t":103.25,"who":"sam","text":"غير مضمون."},{"t":104.72,"who":"nexubo","text":"فهم القيود يتيح لك التعامل مع وقف الخسارة كخطة فعالة، وليس كتميمة حظ."},{"t":116.25,"who":"narrator","text":"كلاهما يحمل اسم BTC. لكن أحدهما قد لا يمنحك أي بيتكوين على الإطلاق. التالي: التداول الفوري والعقود الآجلة."},{"t":123.15,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":18,"title":"التداول الفوري والعقود الآجلة: أنت لا تشتري الشيء نفسه","goal":"التمييز بين حيازة الأصول وحيازة عقود الأسعار، وفهم اتجاه مراكز الشراء ومراكز البيع.","task":"طابق رصيد الأصول الفورية وحقول مراكز العقود الآجلة مع صفحاتها الصحيحة.","answer":"مركز العقود الآجلة لا يعادل أصول العملات القابلة للسحب؛ والدورة لا تطلب منك فتح حساب حقيقي.","takeaways":["السوق الفوري يبادل أصلاً بأصل آخر؛ أما العقد الدائم فهو مركز تعاقدي.","مركز الشراء (Long) يربح إذا ارتفع السعر، ومركز البيع (Short) يربح إذا انخفض؛ والجانب الخاطئ يخسر.","العقود الآجلة بنية مخاطر مختلفة، وليست مستوى يجب أن تصل إليه."],"quiz":{"q":"هل يمنحك مركز العقود الآجلة بيتكوين يمكنك سحبه؟","options":["نعم، إنه مثل السوق الفوري","لا، إنه عقد يسوّي الربح والخسارة","فقط مع رافعة 10x"],"answer":1,"why":"العقد الدائم الخطي يسوّي الربح والخسارة داخل العقد. وليس رصيداً من العملات قابلاً للسحب."},"transcript":[{"t":0.25,"who":"sam","text":"كلاهما يحمل اسم بيتكوين، أليست هذه نفس عملية البيع والشراء؟"},{"t":9.25,"who":"nexubo","text":"التداول الفوري البسيط دون اقتراض يبادل أصلاً بآخر. أما العقود الدائمة الخطية المذكورة هنا، فهي احتفاظ بمركز عقدي يسوي الأرباح والخسائر وفق تغيرات السعر، ولا تعني شراء بيتكوين يمكن سحبه."},{"t":32.25,"who":"narrator","text":"يتوقع مركز الشراء عادة ارتفاع الأسعار، ويتوقع مركز البيع هبوطها. والخطأ في تقدير الاتجاه يؤدي إلى الخسارة في الحالتين. وإمكانية البيع على المكشوف لا تعني أن جني المال أصبح أسهل."},{"t":60.25,"who":"sam","text":"هل يجب أن أنتقل من التداول الفوري إلى العقود الآجلة؟"},{"t":62.38,"who":"nexubo","text":"لا داعي لذلك. العقود الآجلة هيكل مخاطر مختلف وليست مرحلة إلزامية في التعلم؛ ومعرفة ماهيتها تتيح لك أيضاً خيار عدم استخدامها."},{"t":84.25,"who":"narrator","text":"التداول الفوري العادي دون اقتراض لا يخضع للتصفية بسبب نقص الهامش كما في العقود، لكن قيمة الأصول قد تنخفض بشدة. وعدم وجود تصفية قسرية لا يعني ضمان رأس المال."},{"t":103.25,"who":"sam","text":"كلا."},{"t":103.9,"who":"nexubo","text":"ميز أولاً موضوع تداولك قبل أن تدرس الرافعة المالية."},{"t":116.25,"who":"narrator","text":"عند رافعة 10 أضعاف، هل تمنحك المنصة 900 مجاناً؟ في الحلقة القادمة."},{"t":121.25,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":19,"title":"رافعة مالية 10 أضعاف: هل هي أموال أكثر، أم مخاطر أكبر؟","goal":"التمييز بين الهامش والقيمة الاسمية للمركز والعائد؛ وفهم تأثير إعدادات الرافعة المالية عند ثبات حجم المركز.","task":"اختر وضعي الهامش الثابت والمركز الثابت كلاً على حدة، وراقب الربح والخسارة المالية بعد تغيرات الأسعار.","answer":"مع الهامش الثابت، يؤدي رفع الرافعة إلى تضخيم المركز الاسمي؛ ومع المركز الثابت، لا تتضخم الأرباح أو الخسائر المالية تلقائياً.","takeaways":["هامش قدره 100 يتحكم في مركز قيمته 1,000 يعني رافعة 10x.","حركات السعر تؤثر في المركز، وهامشك يتحمل النتيجة.","مع حجم المركز نفسه، تغيير الرافعة يغيّر الهامش، لا الربح والخسارة."],"quiz":{"q":"مركز قيمته 1,000 تحرك 1% عكس اتجاهك، مع تجاهل الرسوم. كم تخسر تقريباً؟","options":["1","10","100"],"answer":1,"why":"1% من مركز قيمته 1,000 تساوي نحو 10، تُخصم من هامشك."},"transcript":[{"t":0.25,"who":"sam","text":"عند استخدام عشرة أضعاف، هل تهديني المنصة 900؟"},{"t":9.25,"who":"nexubo","text":"ليست أموالاً مجانية. بشكل مبسط، 100 من الهامش تتحكم في مركز اسمي بقيمة 1,000 تمثل رافعة 10 أضعاف. تؤثر تغيرات الأسعار على المركز بالكامل، ويتحمل هامشك الأرباح والخسائر الناتجة."},{"t":35.25,"who":"narrator","text":"دون احتساب الرسوم، إذا تحرك السعر بنسبة 1% ضدك، يخسر مركز الـ 1,000 حوالي 10، ومركز الـ 2,000 حوالي 20. قد تبدو النسبة المئوية صغيرة، لكن أثرها كبير جداً على الهامش الصغير."},{"t":67.25,"who":"nexubo","text":"وهناك خطأ شائع آخر: إذا لم يتغير حجم المركز وقمت فقط بتعديل إعداد الرافعة، فلن تتضاعف الأرباح والخسائر المالية من فراغ؛ بل يتغير متطلب الهامش وهامش أمان المخاطر."},{"t":95.25,"who":"narrator","text":"تتضمن التصفية الفعلية هامش الصيانة وسعر التأشير والرسوم؛ والرافعة 10 أضعاف لا تعني حتمية التصفية عند هبوط 10% بالضبط. لا تعتمد على هذا التقريب في التداول الحقيقي."},{"t":116.25,"who":"sam","text":"كلا."},{"t":117.06,"who":"nexubo","text":"ما يتم تضخيمه هو أثر المركز على رأس مالك، وليس دقة حكمك على السوق."},{"t":131.25,"who":"narrator","text":"لماذا يمكن إغلاق صفقتك قسراً قبل أن يصل هامشك إلى الصفر؟ التالي: ذلك الخط غير المرئي."},{"t":137.05,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":20,"title":"لماذا يمكن إغلاق صفقتك قسراً قبل أن يصل هامشك إلى الصفر؟","goal":"التمييز بين الهامش الأولي، وهامش الصيانة، وحقوق الملكية، والرصيد المتاح.","task":"بافتراض رصيد أولي 100 وخسارة غير محققة 20 (دون رسوم)، احسب حقوق الملكية المبسطة بقيمة 80؛ وحدد الحقول المتغيرة.","answer":"حقوق الملكية 80؛ ويجب حساب متطلبات الصيانة وفقاً لقواعد المنتج، ولا تفترض أنها مساوية للهامش الأولي.","takeaways":["الهامش الأولي يفتح المركز؛ وهامش الصيانة يبقيه مفتوحاً.","حقوق الملكية هي الهامش زائد أو ناقص النتيجة المفتوحة: 100 مع خسارة 20 يتبقى 80.","قد يتدخل نظام إدارة المخاطر قبل أن يصل هامشك إلى الصفر."],"quiz":{"q":"الهامش الأولي 100 والمركز خاسر 20، مع تجاهل الرسوم. ما حقوق الملكية المبسطة؟","options":["100","80","120"],"answer":1,"why":"100 ناقص خسارة 20 يتبقى 80، ويستمر هامش الأمان في التقلص إذا تحرك السعر أكثر ضدك."},"transcript":[{"t":0.25,"who":"sam","text":"لا يزال هناك رصيد، لماذا لا يسمحون لي بالانتظار؟"},{"t":9.25,"who":"nexubo","text":"يتطلب فتح المركز هامشاً أولياً؛ وأثناء الاحتفاظ به، يجب عليك أيضاً استيفاء متطلبات هامش الصيانة. فالمبلغ المودع في البداية لا يعني بقاء نفس هامش الأمان لاحقاً."},{"t":35.25,"who":"narrator","text":"لنفترض أن الهامش الأولي 100 والخسارة العائمة 20، بتجاهل البنود الأخرى، تتبقى حقوق ملكية بقيمة 80 فقط. وإذا استمر السعر في التحرك ضدك، فسيواصل هامش الأمان التآكل."},{"t":67.25,"who":"nexubo","text":"عندما تقترب حقوق الملكية من مستوى الصيانة المطلوب من المنصة، قد يتدخل نظام إدارة المخاطر؛ دون انتظار نفاد الرصيد تماماً إلى الصفر. يعتمد ذلك على نوع الحساب ووضع الهامش وقواعد المنتج."},{"t":95.25,"who":"sam","text":"إذاً هل أكون في أمان إذا واصلت إضافة الأموال؟"},{"t":99.06,"who":"nexubo","text":"إضافة الأموال لا تغير اتجاه الأسعار ولا تضمن تجنب التصفية. بل قد تعرض المزيد من أموالك لنفس المخاطرة."},{"t":116.25,"who":"sam","text":"كلا، أحدهما يخص شروط فتح الصفقة والآخر يخص متطلبات استمرار المركز."},{"t":121.2,"who":"nexubo","text":"انظر أولاً إلى حقوق الملكية، ثم انظر إلى مدى بعدها عن خط الإنذار."},{"t":131.25,"who":"narrator","text":"هل وضع 100 في صندوق صغير يحفظ الـ 900 الأخرى بأمان إلى الأبد؟ التالي: الهامش المعزول."},{"t":137.95,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":21,"title":"الهامش المعزول: وضع صفقة واحدة في صندوقها الخاص","goal":"فهم عزل الهامش لكل مركز وكيف يمكن أن تؤدي إضافة الهامش إلى زيادة الأموال المعرضة للمخاطر.","task":"ابحث عن مفتاح الإضافة التلقائية في الإعدادات التجريبية، واشرح سبب تغييره للأموال المعرضة للمخاطرة.","answer":"تزيد الإضافة التلقائية أو اليدوية من الهامش المخصص؛ ولا يمكن التعهد دون قيد أو شرط بخسارة المبلغ الأولي فقط.","takeaways":["الهامش المعزول يمنح المركز الواحد هامشه الخاص.","الهامش الذي خصصته يمكن أن يُفقد؛ فالهامش المعزول ليس وقف خسارة.","الإضافة التلقائية أو اليدوية تضع مزيداً من أموالك خلف المخاطرة نفسها."],"quiz":{"q":"فعّلت الإضافة التلقائية للهامش على مركز معزول. ما الذي يتغير؟","options":["لا شيء، تبقى الخسارة محصورة في أول 100","يمكن أن يتدفق مزيد من رصيدك إلى المركز","يصبح المركز خالياً من المخاطر"],"answer":1,"why":"الإضافة التلقائية تنقل الرصيد المتاح إلى المركز، فيتحمل مزيد من المال المخاطرة."},"transcript":[{"t":0.25,"who":"sam","text":"إذا وضعت 100 كهامش معزول، فهل تصبح الـ 900 الأخرى بعيدة عن اللمس إلى الأبد؟"},{"t":9.25,"who":"nexubo","text":"جوهر الهامش المعزول هو تخصيص هامش منفصل للمركز. وفي الظروف المبسطة دون إيداع إضافي ودون تفعيل الإضافة التلقائية، يتحمل الهامش المخصص وحده مخاطر التصفية بشكل أساسي."},{"t":32.25,"who":"narrator","text":"يسهل ذلك فصل حدود الهامش بين المراكز المختلفة. لكن هذه الـ 100 نفسها تظل معرضة للخسارة؛ فالهامش المعزول لا يمحو الخسائر، ولا يعد أمر وقف خسارة."},{"t":60.25,"who":"nexubo","text":"انتبه لهذا المفتاح: توفر بعض المنصات ميزة الإضافة التلقائية للهامش. وعند تفعيلها، قد يستمر الرصيد المتاح في التدفق إلى المركز. وينطبق الأمر نفسه على الإضافة اليدوية؛ إذ تعرض المزيد من الأموال للمخاطرة."},{"t":84.25,"who":"narrator","text":"لا تفترض أن الحد الأقصى للخسارة سيقتصر إلى الأبد على تلك الـ 100 الأولى لمجرد رؤية كلمة 'معزول'. تحقق دائماً من إعدادات الإضافة والرسوم وقواعد المنتج."},{"t":103.25,"who":"sam","text":"لا يمكن."},{"t":103.99,"who":"nexubo","text":"ينظر الهامش المعزول إلى نطاق العزل، ولكن أيضاً إلى ما إذا كانت هناك قنوات إضافية متصلة به."},{"t":116.25,"who":"narrator","text":"تسرب في مركز واحد، والمركز الآخر يبدأ في الغرق أيضاً. التالي: الهامش المتبادل."},{"t":121.15,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":22,"title":"الهامش المتبادل: لماذا يمكن لخسارة واحدة أن تضرب مراكزك الأخرى","goal":"فهم المخاطر المشتركة لمجمع هامش واحد، دون الخلط بين الهامش المتبادل وكافة أصولك الشخصية.","task":"دع مركزاً افتراضياً يخسر، وراقب كيف تتغير المخاطر في نفس المجمع، وضع دائرة حول الأصول غير الموجودة في مجمع الهامش هذا.","answer":"قد تنتشر المخاطر عبر نفس مجمع الهامش. لكنها لا تشمل تلقائياً جميع أصولك الشخصية.","takeaways":["الهامش المتقاطع يتشارك مجمع هامش واحد بين المراكز.","مركز خاسر واحد قد يستهلك هامش الأمان الذي تعتمد عليه المراكز الأخرى.","لا يصل إلى بطاقاتك المصرفية أو محافظك الشخصية."],"quiz":{"q":"هل الهامش المتقاطع أكثر أماناً تلقائياً؟","options":["نعم، لا يمكن تصفيته أبداً","ليس بالضرورة، فذلك يعتمد على المجمع المشترك والقواعد","نعم، يستخدم جميع بطاقاتك المصرفية"],"answer":1,"why":"الهامش الإضافي قد يؤخر معالجة المخاطر، لكنه يعرّض أيضاً مزيداً من أموالك للخطر."},"transcript":[{"t":0.25,"who":"sam","text":"الخسارة في الجانب الأيسر. لماذا أصبح الجانب الأيمن في خطر أيضاً؟"},{"t":9.25,"who":"nexubo","text":"يشترك الهامش المتبادل في الهامش عبر المراكز، وفقاً لما تسمح به القواعد. لنفترض هنا أن مجمع هامش يحتوي على 1,000. قد تعتمد عدة مراكز عليه، وليس فقط على ما خُصص لكل منها في البداية."},{"t":39.25,"who":"narrator","text":"يمكن لمركز خاسر واحد أن يستنزف هامش الأمان الذي تعتمد عليه المراكز الأخرى. فالأرباح والخسائر والهامش المحجوز للأوامر المفتوحة وقيمة ضماناتك تؤثر جميعها على مخاطر الحساب نفسه."},{"t":75.25,"who":"sam","text":"إذاً فالهامش المتبادل أصعب في التصفية، مما يجعله أكثر أماناً؟"},{"t":79.67,"who":"nexubo","text":"يمكن للأموال الإضافية تأخير وصول المركز إلى معالجة المخاطر. لكنها تعرض أيضاً المزيد من أموالك للخطر لتحمل الخسائر."},{"t":106.25,"who":"narrator","text":"لا يسمح الهامش المتبادل للمنصة باستخدام بطاقاتك المصرفية أو محافظك الشخصية تلقائياً. فتحديد الحسابات والضمانات المشمولة يعتمد على قواعد المنتج. كما قد تخضع الضمانات المعقدة لخصومات في التقييم ومخاطر تقلب أسعارها الخاصة."},{"t":130.25,"who":"sam","text":"ليس بالضرورة. يعتمد ذلك على المجمع المشترك وقواعد الحساب."},{"t":135.19,"who":"nexubo","text":"انظر إلى المجمع بأكمله، وليس فقط إلى مربع مركز واحد."},{"t":146.25,"who":"narrator","text":"السعر الذي تراقبه لم يلمس الخط، لكن جرس الإنذار يدق. التالي: من يضغط زر التصفية."},{"t":152.55,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":23,"title":"التصفية: من ضغط زر الإغلاق القسري؟","goal":"فهم محفزات التصفية وسعر التأشير ومتطلبات الحفاظ على الهامش، دون التعامل مع مقلوب الرافعة كمعادلة دقيقة.","task":"شغّل نفس حركة السوق الافتراضية بالهبوط ثم الصعود، وراقب التداول الفوري البسيط وعقد الهامش المعزول المبسط كلاً على حدة.","answer":"مسار السعر بالغ الأهمية. فالعقد الذي تم تصفيته في منتصف الطريق لن تعيده أي ارتدادة لاحقة.","takeaways":["كثير من العقود الدائمة تحدد التصفية بناءً على سعر العلامة (Mark Price) وقواعد الهامش، لا آخر صفقة.","عند الاقتراب من متطلب الصيانة، يمكن للنظام تقليص المركز أو إغلاقه.","المركز المغلق لا يعود عندما يرتد السعر."],"quiz":{"q":"تمت تصفية مركز برافعة مالية، ثم عاد السعر للارتفاع لاحقاً. ماذا يحدث؟","options":["يعود المركز من تلقاء نفسه","يبقى مغلقاً؛ فالمسار هو ما كان يهم","تعيد المنصة قيمة الخسارة"],"answer":1,"why":"بمجرد إغلاقه قسرياً، يختفي المركز. والارتداد اللاحق يفيد فقط من لا يزال محتفظاً بمركزه."},"transcript":[{"t":0.25,"who":"sam","text":"السعر الذي أراقبه لم يصل إلى هناك بعد. لماذا يدق جرس الإنذار؟"},{"t":9.25,"who":"nexubo","text":"ليس آخر سعر تداول هو السعر المستخدم دائماً لتحديد التصفية. فالعديد من العقود الدائمة تقيّم المخاطر باستخدام سعر التأشير وقواعد الهامش. تحقق من القواعد التي تستخدمها منصتك فعلياً."},{"t":35.25,"who":"narrator","text":"عندما يتحرك السعر ضد المركز، تأكل الخسائر حقوق الملكية. بالقرب من متطلبات الحفاظ، قد يقوم النظام بإلغاء الأوامر أو تخفيض المركز أو إغلاقه قسراً، دون انتظار موافقتك."},{"t":67.25,"who":"nexubo","text":"تشير التصفية عادة إلى حدث مخاطر الإغلاق القسري هذا، وليس عطلاً في زر هاتفك. ويعتمد المحفز الفعلي على الرسوم، وهامش الصيانة، ووضع الهامش، وغيرها. 10 أضعاف لا تعني هبوطاً بنسبة 10% تماماً."},{"t":95.25,"who":"sam","text":"لقد عاد وارتفع لاحقاً. ألا يمكنني الانتظار حتى يعود؟"},{"t":99.46,"who":"nexubo","text":"المركز المغلق لا يعود من تلقاء نفسه. فهبوط السعر ثم صعوده قد ينتهي بنتيجة مختلفة تماماً لمركز برافعة مالية مقارنة بالتداول الفوري البسيط الذي احتفظت به فحسب."},{"t":116.25,"who":"sam","text":"غير مضمون."},{"t":117.73,"who":"nexubo","text":"المهم ليس الوجهة فقط، بل هل يمكنك النجاة طوال هذا المسار."},{"t":131.25,"who":"narrator","text":"السعر لم يتحرك تقريباً ولم تغلق المركز، لكن رصيدك انخفض. الحلقة الأخيرة قادمة."},{"t":137.35,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]},{"ep":24,"title":"السعر ثابت والرصيد ينخفض؟ أنهِ المستوى الأخير مع وضع التكاليف في الحسبان","goal":"معرفة اتجاه وأساس رسوم التمويل، وإجراء فحص شامل لمخاطر العقود الآجلة، والقدرة على اختيار عدم التداول.","task":"احسب رسوم فترة واحدة بقيمة 0.10 وأكمل قائمة فحص أوامر العقود الآجلة الافتراضية. يُمنع منعاً باتاً استدعاء واجهات برمجة التطبيقات للأوامر الحقيقية.","answer":"معدل موجب: أصحاب مراكز الشراء يدفعون وأصحاب مراكز البيع يستلمون. الرسوم في هذا المثال: 0.10. يُعتبر الاختبار ناجحاً بالإجابة الصحيحة على جميع أسئلة المخاطر الرئيسية، أو باختيار عدم التداول بوضوح.","takeaways":["رسوم التمويل تُدفع بين مراكز الشراء ومراكز البيع، وليست رسماً ثابتاً للمنصة.","تُحسب على قيمة المركز: 1,000 بنسبة 0.01% تساوي 0.10.","اختيار عدم التداول إجابة ناجحة أيضاً."],"quiz":{"q":"معدل التمويل موجب. من يدفع عادةً؟","options":["مراكز البيع تدفع لمراكز الشراء","مراكز الشراء تدفع لمراكز البيع","الجميع يدفع للمنصة"],"answer":1,"why":"مع المعدل الموجب، تدفع مراكز الشراء عادةً لمراكز البيع. ومع المعدل السالب ينعكس الأمر."},"transcript":[{"t":0.25,"who":"sam","text":"السعر لم يتحرك تقريباً ولم أغلق المركز. لماذا رصيدي أقل؟"},{"t":9.25,"who":"nexubo","text":"بالإضافة إلى رسوم التداول، تحتوي العقود الدائمة عادةً على آلية تمويل. عندما يكون المعدل موجباً، يدفع أصحاب الشراء لأصحاب البيع. وعندما يكون سالباً، ينعكس الأمر. إنها ليست فائدة ثابتة يدفعها الجميع للمنصة."},{"t":42.25,"who":"narrator","text":"لنفترض أن قيمة المركز عند التسوية هي 1,000 والمعدل هو 0.01%. تكون هذه الرسوم 0.10. وهي محسوبة على قيمة المركز الإجمالية، وليس على هامش الـ 100 الأول لديك."},{"t":83.25,"who":"nexubo","text":"قد يتغير الفاصل الزمني والمعدل حسب زوج التداول والمنصة والسوق. فلا تحفظها كقاعدة ثابتة بأنها 'كل عقد، كل ثماني ساعات، إلى الأبد'. ولا تعامل استلام التمويل كدخل خالٍ من المخاطر."},{"t":117.25,"who":"narrator","text":"المستوى الأخير مخصص للتدريب فقط. أولاً، اشرح ما الذي تتداوله وفي أي اتجاه. ثم تحقق من الوضع والحجم والهامش والإضافة التلقائية وخطة الخروج والتكاليف. إذا لم تفهم عنصراً واحداً، فتوقف. لا تخمن طريقك عبر الأزرار."},{"t":144.25,"who":"sam","text":"أعرف كيفية القيام بذلك، وأعلم أن هذه المخاطرة لا تناسبني. لذا لن أتداول."},{"t":149.09,"who":"nexubo","text":"هذه نتيجة نجاح أيضاً. إنهاء الدورة لا يعني أنك ستجني المال بالضرورة. افهم أولاً، ثم تصرّف."},{"t":172.75,"who":"narrator","text":"لقد أكملت الموسمين. اختر الحلقة التي شعرت أنها الأصعب، وأعد مشاهدتها قبل أن تتداول على الإطلاق."},{"t":178.65,"who":"narrator","text":"افهم أولاً، ثم تصرّف."}]}]});
